DDL = '\n            CREATE TABLE IF NOT EXISTS devices (\n                tenant TEXT NOT NULL, id TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL,\n                scope TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0,\n                session TEXT, installation TEXT, hello TEXT, heartbeat TEXT, seen REAL,\n                PRIMARY KEY(tenant,id), UNIQUE(id));\n            CREATE TABLE IF NOT EXISTS media (\n                tenant TEXT NOT NULL, id TEXT NOT NULL, sha256 TEXT NOT NULL,\n                md5 TEXT NOT NULL, size INTEGER NOT NULL, mime TEXT NOT NULL, data BLOB NOT NULL,\n                PRIMARY KEY(tenant,id), UNIQUE(tenant,sha256));\n            CREATE TABLE IF NOT EXISTS tasks (\n                tenant TEXT NOT NULL, id TEXT PRIMARY KEY, device TEXT NOT NULL,\n                dedup TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL,\n                created REAL NOT NULL, deadline REAL NOT NULL,\n                lease_token TEXT, lease_until REAL, session TEXT, intent_at REAL,\n                submitted_at REAL, updated REAL NOT NULL,\n                UNIQUE(tenant,dedup), FOREIGN KEY(tenant,device) REFERENCES devices(tenant,id));\n            CREATE INDEX IF NOT EXISTS tasks_device_state ON tasks(tenant,device,state,created);\n            CREATE INDEX IF NOT EXISTS tasks_state ON tasks(state);\n            CREATE TABLE IF NOT EXISTS events (\n                seq INTEGER PRIMARY KEY AUTOINCREMENT, tenant TEXT NOT NULL, task TEXT NOT NULL,\n                event_id TEXT NOT NULL, at REAL NOT NULL, state TEXT NOT NULL, details TEXT NOT NULL,\n                UNIQUE(task,event_id), FOREIGN KEY(task) REFERENCES tasks(id));\n            CREATE TABLE IF NOT EXISTS archive_claims (\n                tenant TEXT NOT NULL, event_id TEXT NOT NULL, task TEXT NOT NULL,\n                PRIMARY KEY(tenant,event_id), FOREIGN KEY(task) REFERENCES tasks(id));\n            '
